      "id": "decision-0004",
      "status": "fail",
      "findings": [
        {
          "dimension": "physical route",
          "fact": "South’s club honors cannot win this trick after South has already played C3.",
          "explanation": "The current trick is South C3, West C4. After dummy plays C5, only East remains to play; South cannot contribute CK or CQ to this trick.",
          "quotes": ["South’s king and queen can take the club trick if East does not overcall."]
        }
      ]
    },
    {
      "id": "decision-0005",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner accuracy",
          "fact": "HK securely wins the heart continuation while preserving HQ.",
          "explanation": "HA has already been played, East has led HT, and South holds HK. Dummy’s HQ and CA remain available, supporting the proposed diamond development and entry.",
          "quotes": ["Cover East’s heart ten with the king to secure the trick while retaining dummy’s queen."]
        }
      ]
    },
    {
      "id": "decision-0006",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner preservation",
          "fact": "H8 preserves HQ without sacrificing the current trick.",
          "explanation": "South’s HK is already beating East’s HT and West’s H3. Dummy is last to play and holds H8 and HQ.",
          "quotes": ["Play low; South’s king is winning, so preserve dummy’s queen for a later heart trick."]
        }
      ]
    },
    {
      "id": "decision-0007",
      "status": "fail",
      "findings": [
        {
          "dimension": "trick counting",
          "fact": "An extra diamond trick is not needed to make 3NT.",
          "explanation": "Declarer has won two tricks and has seven available top winners: SA, SK, HQ, DA, CA, CK and CQ. These can be collected using the available heart, club and spade connections. The stated need for an additional trick miscounts the contract.",
          "quotes": ["Lead a low diamond toward dummy’s queen-jack to seek the extra trick needed for 3NT."]
        }
      ]
    },
    {
      "id": "decision-0008",
      "status": "pass",
      "findings": [
        {
          "dimension": "conditional reasoning",
          "fact": "DQ is a feasible finesse attempt, and its success is explicitly conditional.",
          "explanation": "South has led D2, West has played D5, and dummy holds DQ and DJ. East’s DK location is unknown at this decision. South’s SA provides an available return entry for another lead toward DJ.",
          "quotes": ["Take the diamond finesse with the queen; if it holds, dummy’s jack remains available for another attempt."]
        }
      ]
    },
    {
      "id": "decision-0009",
      "status": "pass",
      "findings": [
        {
          "dimension": "contract route",
          "fact": "The proposed cashing route supplies the six tricks needed for the contract.",
          "explanation": "Declarer has three tricks. CA, CK, CQ, SA, SK and DA supply six more. Dummy’s remaining C6 reaches South’s club honors, and spade connections permit collection of both top spades and DA.",
          "quotes": ["Cash the club ace, then lead the remaining club toward South’s king-queen. Follow with the top spades and diamond ace, aiming to reach nine tricks without risking a finesse."]
        }
      ]
    },
    {
      "id": "decision-0010",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner preservation",
          "fact": "Playing C8 under CA preserves two separate club winners.",
          "explanation": "Dummy’s CA is winning the current trick, and South holds CK, CQ and C8. Following with C8 leaves CK and CQ for dummy’s remaining C6 lead.",
          "quotes": ["Discard a low club under dummy’s ace, preserving South’s king and queen to cash later."]
        }
      ]
    },
    {
      "id": "decision-0011",
      "status": "pass",
      "findings": [
        {
          "dimension": "entry feasibility",
          "fact": "C6 provides a direct route to South’s winning club honors.",
          "explanation": "Dummy is on lead holding C6, and South retains CK and CQ. CA has already been cashed, so either South honor can win the club lead.",
          "quotes": ["Lead the last dummy club toward South’s king-queen to cash another club winner."]
        }
      ]
    },
    {
      "id": "decision-0012",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner accuracy",
          "fact": "CK beats East’s CJ and preserves CQ as another winner.",
          "explanation": "The current trick is C6, CJ; CA has already been played. South holds CK and CQ, so CK cannot be beaten by West.",
          "quotes": ["Cover East’s jack with the king to win the club trick and preserve the queen."]
        }
      ]
    },
    {
      "id": "decision-0013",
      "status": "pass",
      "findings": [
        {
          "dimension": "contract route",
          "fact": "CQ is a sure winner, followed by sufficient top cards to make 3NT.",
          "explanation": "Declarer has five tricks and retains CQ, SA, SK and DA. These four winners are accessible through the remaining spade connections.",
          "quotes": ["Cash the now-top club queen before switching to the spade and diamond winners."]
        }
      ]
    },
    {
      "id": "decision-0014",
      "status": "pass",
      "findings": [
        {
          "dimension": "discard feasibility",
          "fact": "D3 is a legal discard that preserves the remaining winners and diamond strength.",
          "explanation": "Dummy has no clubs on South’s CQ lead and holds SK, S7, S2, DJ, D9 and D3. Discarding D3 retains SK and both higher diamonds.",
          "quotes": ["Discard a low diamond, preserving dummy’s spade honors and diamond jack-nine for the remaining tricks."]
        }
      ]
    },
    {
      "id": "decision-0015",
      "status": "pass",
      "findings": [
        {
          "dimension": "contract route",
          "fact": "SA followed by a spade to SK is feasible, with DA accessible afterward.",
          "explanation": "Declarer has six tricks. South holds SA, S6, S4, DA and D7; dummy holds SK and two low spades plus DJ and D9. After the two top spades, dummy can lead a diamond to DA for the ninth trick.",
          "quotes": ["Cash the spade ace, then lead toward dummy’s king. Use the diamond ace and jack as the remaining source of tricks if needed."]
        }
      ]
    },
    {
      "id": "decision-0016",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner preservation",
          "fact": "S2 under SA preserves SK as a separate winner.",
          "explanation": "South’s SA is already winning over West’s S9. Dummy holds S2, S7 and SK, and South retains low spades to reach SK later.",
          "quotes": ["Play low under South’s ace, preserving dummy’s king for a later spade trick."]
        }
      ]
    },
    {
      "id": "decision-0017",
      "status": "fail",
      "findings": [
        {
          "dimension": "condition coherence",
          "fact": "The proposed failure of DJ is impossible, and SK does not require a finesse.",
          "explanation": "DK and DQ have already been played, making dummy’s DJ the highest outstanding diamond. After DA, South’s D7 can reach it securely. SA has also been played, so dummy’s SK is a top winner rather than a finesse position.",
          "quotes": ["Cash the diamond ace, then lead a low diamond toward dummy’s jack for the needed extra trick; if that fails, try the spade finesse to dummy’s king."]
        }
      ]
    },
    {
      "id": "decision-0018",
      "status": "fail",
      "findings": [
        {
          "dimension": "retained plan coherence",
          "fact": "The retained plan still treats a guaranteed diamond winner as fallible and proposes a nonexistent spade finesse.",
          "explanation": "D9 legally preserves DJ under DA, but the effective plan retains a material false contingency. DK and DQ are already gone, and SA has been cashed; DJ and SK are top cards.",
          "quotes": ["if that fails, try the spade finesse to dummy’s king."]
        }
      ]
    },
    {
      "id": "decision-0019",
      "status": "fail",
      "findings": [
        {
          "dimension": "retained plan coherence",
          "fact": "The current diamond lead is sound, but its retained fallback remains incoherent.",
          "explanation": "With eight tricks won, D7 toward DJ guarantees the ninth because DK and DQ have already been played. The effective plan nevertheless retains an impossible failure condition and calls the established SK a finesse.",
          "quotes": ["if that fails, try the spade finesse to dummy’s king."]
        }
      ]
    },
    {
      "id": "decision-0020",
      "status": "pass",
      "findings": [
        {
          "dimension": "objective and winner accuracy",
          "fact": "Leading SK collects a sure overtrick after the contract is made.",
          "explanation": "Declarer has nine tricks, SA has already been played, and dummy holds SK and S7. SK is the highest remaining spade and can safely be cashed.",
          "quotes": ["With the contract already made, cash dummy’s king as a low-risk overtrick attempt."]
        }
      ]
    },
    {
      "id": "decision-0021",
      "status": "pass",
      "findings": [
        {
          "dimension": "legal continuation",
          "fact": "S4 follows suit under dummy’s winning SK and retains S6.",
          "explanation": "The current trick is North SK, East SJ. South holds only S6 and S4, and SA has already been played, so S4 is a sound legal continuation.",
          "quotes": ["Play a low spade under dummy’s king, preserving the six for later."]
        }
      ]
    }
  ]
